    # Let's use a SAT solver or simple backtracking
    # Since n=21, 2^21 is 2 million, we can just brute force it in C or Python with pruning.

    code = """
#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 21;
    int seq[21];
    for (int i = 0; i < (1 << 21); i++) {
        for (int j = 0; j < 21; j++) {
            seq[j] = (i & (1 << j)) ? 1 : -1;
        }
        if (seq[5] != -1) continue;
        if (seq[12] != -1) continue;
        if (seq[17] != 1) continue;
        if (seq[20] != 1) continue;

        int C[21];
        for (int k = 1; k < 21; k++) {
            C[k] = 0;
            for (int j = 0; j < 21 - k; j++) {
                C[k] += seq[j] * seq[j + k];
            }
        }

        if (C[1] != 2) continue;
        if (C[2] != -1) continue;
        if (C[9] != 2) continue;
        if (C[20] != -1) continue;

        int sum_C2 = 0;
        for (int k = 1; k < 21; k++) {
            sum_C2 += C[k] * C[k];
        }

        if (sum_C2 <= 52) {
            for (int j = 0; j < 21; j++) {
                printf("%d ", seq[j]);
            }
            printf("\\n");
            return 0;
        }
    }
    printf("UNSAT\\n");
    return 0;
}
"""
